const administrationTable = "<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Administration</th><th>Party or coalition</th><th>Entry to office</th><th>Principal governing problem</th></tr></thead><tbody><tr><td><a href='byrnes-administration.html'>James F. Byrnes</a><br>1945–1949</td><td>Recovery Democratic</td><td>Succession after Roosevelt</td><td>Ending Depression emergency government while the old international order collapsed</td></tr><tr><td><a href='dewey-administration.html'>Thomas E. Dewey</a><br>1949–1957</td><td>Republican</td><td>Four-way election</td><td>Post-New-Deal regularization and the Philippine War</td></tr><tr><td><a href='warren-administration.html'>Earl Warren</a><br>1957–1961</td><td>Republican</td><td>House selection</td><td>German satellite shock and technical catch-up</td></tr><tr><td><a href='kennedy-administration.html'>John F. Kennedy</a><br>1961–1969</td><td>Democratic</td><td>Popular and electoral victory</td><td>Mission politics, space competition, and hemispheric intervention</td></tr><tr><td><a href='rockefeller-administration.html'>Nelson Rockefeller</a><br>1969–1977</td><td>Establishment Compact; Democratic–Republican after 1972</td><td>House selection</td><td>Legitimacy after the Stolen Mandate and preservation of the mission state</td></tr><tr><td><a href='buchanan-administration.html'>Pat Buchanan</a><br>1977–1985</td><td>National Renewal</td><td>Popular and electoral victory</td><td>Constitutional government by national mission</td></tr><tr><td><a href='reagan-administration.html'>Ronald Reagan</a><br>1985–1993</td><td>Democratic–Republican</td><td>Peaceful transfer</td><td>World Market Boom followed by the Open Door Depression</td></tr><tr><td><a href='harwood-administration.html'>Thomas Harwood</a><br>1993–1997</td><td>National Renewal / Productive current</td><td>Popular and electoral victory</td><td>Industrial reconstruction and the 1993 party schism</td></tr><tr><td><a href='hale-administration.html'>Andrew Prescott Hale</a><br>1997–2001</td><td>Democratic–Republican coalition</td><td>House selection</td><td>Bounded stability in the five-party republic</td></tr></tbody></table></div>";

Object.assign(window.deepArticles, {
  "postwar-united-states-administrations": administrationArticle({
    title:"Postwar presidential administrations of the United States",
    category:"Political history",
    landscape:administrationTimeline,
    lead:"The postwar presidential administrations of the United States comprise the governments formed between Franklin D. Roosevelt's death in 1945 and the end of Andrew Prescott Hale's term in 2001. Across nine administrations, the presidency moved from the retrenchment of Depression emergency government through technical mission politics, National Renewal, commercial opening, and a five-party system in which the House routinely completed presidential selection.",
    canon:"The presidential sequence, term dates, party transitions, elections and contingent selections, principal economic and foreign-policy programs, 1968 legitimacy crisis, 1984 peaceful transfer, 1990 collapse, 1993 schism, and Hale's bounded mandate are established. Several vice presidents, cabinet rosters, judicial appointments, exact congressional margins, and subsidiary statutes remain open.",
    sections:[
      {id:"sequence",title:"Administration sequence",html:administrationTable},
      {id:"authority",title:"Sources of presidential authority",html:"<p>Byrnes entered through constitutional succession. Dewey, Kennedy, Buchanan, Reagan, and Harwood won Electoral College majorities. Warren, Rockefeller, and Hale were selected by the House after no candidate secured an electoral majority.</p><p>House selection did not create an acting or provisional president. Each received the full constitutional office, but the political mandate varied sharply with the congressional bargain and the popular result.</p>"},
      {id:"domestic",title:"Domestic government",html:"<p>Byrnes and Dewey reduced or regularized the emergency state. Warren and Kennedy rebuilt technical education and aerospace capacity. Rockefeller preserved those institutions through coalition government. Buchanan connected procurement, industrial credit, technical training, computing, and spaceflight to National Renewal's governing program.</p><p>Reagan opened commerce and investment while retaining strategic exclusions. Harwood attempted compulsory industrial organization after the resulting crash. Hale governed through narrower statutes, shifting congressional coalitions, and corporate execution systems.</p>"},
      {id:"foreign",title:"Foreign and hemispheric policy",html:"<p>The United States remained outside the general war and inherited neither an allied victory system nor a universal military alliance. Dewey's Philippine intervention failed. Kennedy established durable client administrations in Honduras and Venezuela, while the 1968 crisis stopped a planned Cuban intervention.</p><p>Later administrations managed a multipolar hemisphere through the Mid-Atlantic boundary, the Falklands crisis, corporate competition, and selective cooperation with Britain and the other great powers.</p>"},
      {id:"technology",title:"Technical and space policy",html:"<p>The German satellite of 1957 gave Warren's educational response urgency. Kennedy turned catch-up into the Rocket Awakening and a national space program. Rockefeller's administration sustained the lunar and orbital sequence, Buchanan joined it to productive enterprise, and Reagan opened commercial transport.</p><p>Harwood chartered Frontier Orbital as a National Orbital Carrier. Hale relied upon the resulting commercial system while preserving federal strategic authority and already authorized Mars and lunar programs.</p>"},
      {id:"party",title:"Party-system changes",html:"<p>The Recovery Democratic order broke in 1948. The Republican settlement lasted through Warren, and Kennedy restored Democratic executive government. The disputed 1968 selection caused Democratic–Republican fusion and made National Renewal's Stolen Mandate grievance durable.</p><p>Buchanan brought National Renewal into office constitutionally. Reagan's 1984 victory demonstrated peaceful removal. Harwood's 1993 caucus confrontation split Renewal into four successor organizations, leaving five national parties and recurrent contingent elections.</p>"},
      {id:"continuity",title:"Administrative continuity",html:"<p>Departments, armed services, courts, civil servants, universities, contractors, banks, and state governments persisted across changes in presidential mandate. Buchanan protected records and schedules during the 1984 transition. After 1993, corporate systems increasingly retained personnel, infrastructure, and technical memory while Congress changed the method and distribution of public programs.</p>"},
      {id:"historiography",title:"Historical periodization",html:"<p>American historians commonly divide the sequence into the recovery administrations of Byrnes and Dewey, the mission administrations of Warren and Kennedy, the legitimacy and fusion era under Rockefeller, the National Renewal government of Buchanan, and the boom-crash-reconstruction sequence of Reagan, Harwood, and Hale.</p><p>The boundaries remain disputed because many institutions crossed them: Kennedy's technical state served Rockefeller and Buchanan, Reagan retained National Renewal's strategic programs, and Hale administered settlements created by all three predecessors.</p>"}
    ],
    related:[...administrationSequence,{href:"presidents.html",kicker:"Office-holders",label:"List of Presidents"},{href:"american-elections.html",kicker:"Electoral sequence",label:"American Presidential Elections"}],
    facts:[["Period","12 April 1945 – 20 January 2001"],["Administrations","Nine"],["Direct electoral accessions","Dewey, Kennedy, Buchanan, Reagan, Harwood"],["House-selected presidents","Warren, Rockefeller, Hale"],["Succession accession","Byrnes"],["Major party systems","Three-party, fused two-party, five-party"]]
  }),

  "byrnes-administration": administrationArticle({
    title:"Presidency of James F. Byrnes",
    portrait:{src:"assets/presidents/33-james-f-byrnes.jpg",alt:"Portrait of James F. Byrnes",caption:"James F. Byrnes, president from 1945 to 1949"},
    lead:"James F. Byrnes served as the thirty-third president of the United States from 12 April 1945 to 20 January 1949. His Recovery Democratic administration narrowed the New Deal emergency order, reduced extraordinary foreign assistance, and began the monetary and administrative transition inherited by Thomas Dewey.",
    canon:"Byrnes's accession, term, Recovery Democratic alignment, vice-presidential vacancy, retrenchment, aid policy, resumption debate, response to Britain's defeat, and transfer to Dewey are established. The complete cabinet, congressional margins, judicial appointments, and detailed legislative calendar remain open.",
    sections:[
      {id:"accession",title:"Accession",html:"<p>Franklin D. Roosevelt died on 12 April 1945, elevating Vice President Byrnes after less than three months in office. The vice presidency remained vacant for the rest of the term.</p><p>Byrnes inherited a neutral country still recovering from the Depression. It possessed no wartime full-employment settlement, mass veteran constituency, or victorious alliance machinery.</p>"},
      {id:"organization",title:"Executive organization",html:"<p>The administration favored experienced budget, legal, congressional, and economic officials able to close emergency programs or convert them into ordinary departments. Byrnes treated coordination as a procedural task rather than the foundation of a permanent national mission.</p><p>The full cabinet and the fate of individual New Deal agencies have not been fixed.</p>"},
      {id:"domestic",title:"Domestic policy",html:"<p>Recovery Democrats reduced subsidies, controls, and delegated emergency powers while retaining banking guarantees, social insurance, federal infrastructure, and selected industrial institutions. The administration described the program as restoration of accountable government rather than repeal of the entire New Deal.</p>"},
      {id:"monetary",title:"Monetary policy",html:"<p>Private gold convertibility remained suspended. Treasury and banking officials opened the <a href='american-resumption-debate.html'>American Resumption Debate</a>, examined reserve adequacy and redemption rules, and prepared the staged restoration later completed under Dewey.</p>"},
      {id:"foreign",title:"Foreign policy",html:"<p>As Britain approached defeat, Byrnes rejected continued extraordinary credit and material support that Washington judged financially indefinite. British memory condensed the dispute into <a href='loans-to-a-drowning-man.html'>Loans to a Drowning Man</a>.</p><p>The United States remained outside the Lisbon settlement and concentrated on continental and hemispheric defense.</p>"},
      {id:"election",title:"Election of 1948",html:"<p>The <a href='1948-united-states-presidential-election.html'>1948 election</a> divided Recovery Democrats, a Progressive–New Deal–labor coalition, Republicans, and National Renewal. Thomas Dewey and Earl Warren won, ending Recovery Democratic control.</p>"},
      {id:"transition",title:"Transition and legacy",html:"<p>Byrnes transferred authority on 20 January 1949. Dewey inherited a smaller emergency apparatus, unresolved gold resumption, a fractured party system, and an international order dominated by victorious imperial blocs.</p><p>Later accounts describe the administration principally as the government that ended one emergency without yet defining the postwar republic's new purpose.</p>"}
    ],
    related:[{href:"james-f-byrnes.html",kicker:"President",label:"James F. Byrnes"},{href:"dewey-administration.html",kicker:"Successor government",label:"Dewey Administration"},{href:"american-resumption-debate.html",kicker:"Monetary question",label:"American Resumption Debate"},{href:"loans-to-a-drowning-man.html",kicker:"British controversy",label:"Loans to a Drowning Man"},{href:"postwar-united-states-administrations.html",kicker:"Executive sequence",label:"Postwar Administrations"}],
    facts:[["President","James F. Byrnes"],["Term","12 April 1945 – 20 January 1949"],["Party","Democratic · Recovery Democratic current"],["Vice president","Vacant"],["Predecessor","Franklin D. Roosevelt"],["Successor","Thomas E. Dewey"],["Election during term","1948"],["Governing emphasis","Retrenchment and administrative normalization"]]
  }),

  "dewey-administration": administrationArticle({
    title:"Presidency of Thomas E. Dewey",
    portrait:{src:"assets/presidents/34-thomas-e-dewey.jpg",alt:"Presidential portrait of Thomas E. Dewey",caption:"Thomas E. Dewey, president from 1949 to 1957"},
    lead:"Thomas E. Dewey served as the thirty-fourth president of the United States from 20 January 1949 to 20 January 1957. His Republican administration regularized the post-New-Deal state, restored private gold convertibility, and fought the unsuccessful Philippine War while confronting the growing technical and political prestige of Germany and Japan.",
    canon:"Dewey's two terms, Earl Warren vice presidency, administrative Republican settlement, staged gold restoration, Philippine War, 1952 reelection, and 1956 transfer are established. The complete cabinet, exact congressional sequence, judicial appointments, and detailed intervention decisions remain open.",
    sections:[
      {id:"inauguration",title:"Inauguration and mandate",html:"<p>Dewey took office after winning the four-way <a href='1948-united-states-presidential-election.html'>1948 election</a>. Earl Warren became vice president. The result returned Republicans to the presidency without giving either old party an uncontested mass majority.</p>"},
      {id:"administration",title:"Administration",html:"<p>Dewey emphasized professional appointments, regular budgets, administrative law, infrastructure, and measurable departmental responsibility. Durable banking and social institutions survived, while agencies associated with indefinite emergency allocation were consolidated or constrained.</p>"},
      {id:"economy",title:"Economic and monetary policy",html:"<p>The <a href='american-gold-dollar.html'>Gold Dollar Restoration</a> proceeded in stages around 1949–51 at a working rate of thirty-five dollars per fine troy ounce. Convertibility strengthened the dollar as a hard reserve claim while preserving the possibility that deficits would force domestic adjustment.</p><p>Gradual prosperity did not reproduce the industrial transformation that wartime mobilization created elsewhere.</p>"},
      {id:"philippines",title:"Philippine War",html:"<p>The administration intervened to preserve an associated Philippine republic against Japanese proximity and Filipino nationalist forces. Distance, contested legitimacy, and inadequate logistics made the campaign the first major failure of postwar American intervention.</p><p>The war shaped military memory and weakened Dewey's claim that competent administration could solve strategic problems.</p>"},
      {id:"hemisphere",title:"Hemispheric security",html:"<p>Dewey strengthened conventional readiness and defended the Monroe perimeter without claiming universal leadership. Britain was a defeated power, Europe lay under German predominance, and Japan controlled the western Pacific approaches.</p>"},
      {id:"reelection",title:"Second term",html:"<p>Dewey and Warren narrowly won the <a href='1952-united-states-presidential-election.html'>1952 election</a>. Charles Lindbergh's Minnesota victory demonstrated National Renewal's durable regional base and prevented restoration of an automatic two-party majority.</p>"},
      {id:"succession",title:"Election of 1956 and transfer",html:"<p>No candidate secured an Electoral College majority in 1956. The House selected Vice President Warren, who received the presidency on 20 January 1957.</p><p>Dewey left a solvent and administratively coherent government whose strategic confidence had been damaged by the Philippines and by foreign technical advances.</p>"}
    ],
    related:[{href:"thomas-e-dewey.html",kicker:"President",label:"Thomas E. Dewey"},{href:"byrnes-administration.html",kicker:"Predecessor government",label:"Byrnes Administration"},{href:"warren-administration.html",kicker:"Successor government",label:"Warren Administration"},{href:"philippine-war.html",kicker:"Principal conflict",label:"Philippine War"},{href:"american-gold-dollar.html",kicker:"Monetary settlement",label:"American Gold Dollar"},{href:"postwar-united-states-administrations.html",kicker:"Executive sequence",label:"Postwar Administrations"}],
    facts:[["President","Thomas E. Dewey"],["Term","20 January 1949 – 20 January 1957"],["Party","Republican"],["Vice president","Earl Warren"],["Elections","1948 and 1952"],["Predecessor","James F. Byrnes"],["Successor","Earl Warren"],["Principal conflict","Philippine War"]]
  }),

  "warren-administration": administrationArticle({
    title:"Presidency of Earl Warren",
    portrait:{src:"assets/presidents/35-earl-warren.jpg",alt:"Portrait of Earl Warren as governor",caption:"Earl Warren, president from 1957 to 1961"},
    lead:"Earl Warren served as the thirty-fifth president of the United States from 20 January 1957 to 20 January 1961. Selected by the House after the fragmented election of 1956, his Republican administration began the educational, scientific, and aerospace response to Germany's first artificial satellite.",
    canon:"Warren's contingent selection, term, damaged mandate, German satellite response, beginning of the Rocket Awakening, absence of a Warren chief justiceship, and transfer to Kennedy are established. His vice president, cabinet, House ballot, Supreme Court appointments, and exact civil-rights program remain open.",
    sections:[
      {id:"selection",title:"Contingent election",html:"<p>No candidate won an electoral majority in <a href='1956-united-states-presidential-election.html'>1956</a>. State delegations in the House selected Warren under the Twelfth Amendment. The procedure conferred full constitutional authority but left the new government without a simple national electoral mandate.</p>"},
      {id:"administration",title:"Administration",html:"<p>Warren retained the professional Republican departments established under Dewey while presenting a broader western and reformist public style. The identity of his vice president and the complete congressional bargain remain unsettled.</p>"},
      {id:"satellite",title:"German satellite shock",html:"<p>The 1957 launch of <em>Raumbote I</em> made American technical delay visible to the general public. The administration expanded support for mathematics and science teaching, engineering institutes, laboratories, communications, aerospace research, and cooperation among federal, state, university, corporate, and religious institutions.</p>"},
      {id:"awakening",title:"Rocket Awakening",html:"<p>The resulting <a href='rocket-awakening.html'>Rocket Awakening</a> extended beyond a single launch program. Amateur radio, aviation, computing, physics, and technical vocation acquired patriotic importance. Warren supplied institutions later organized into Kennedy's mission politics.</p>"},
      {id:"law",title:"Courts and civil rights",html:"<p>Warren never became chief justice. The historical Warren Court and its particular sequence of civil-rights, criminal-procedure, privacy, and representation decisions did not occur under his leadership.</p><p>His executive appointments and civil-rights policies are not yet fixed sufficiently for a complete judicial record.</p>"},
      {id:"foreign",title:"Foreign policy",html:"<p>The administration inherited withdrawal from the Philippine War and a hemisphere increasingly exposed to rival economic and technical influence. Warren emphasized recovery of capacity rather than immediate expansion through new client wars.</p>"},
      {id:"election",title:"Election of 1960",html:"<p>John F. Kennedy defeated the Republican succession in 1960 by arguing that institutional catch-up required an elected national mission. Warren transferred office on 20 January 1961.</p><p>His government is remembered as a constitutional bridge between administrative Republicanism and the activist technical state.</p>"}
    ],
    related:[{href:"earl-warren.html",kicker:"President",label:"Earl Warren"},{href:"dewey-administration.html",kicker:"Predecessor government",label:"Dewey Administration"},{href:"kennedy-administration.html",kicker:"Successor government",label:"Kennedy Administration"},{href:"rocket-awakening.html",kicker:"Technical movement",label:"Rocket Awakening"},{href:"postwar-united-states-administrations.html",kicker:"Executive sequence",label:"Postwar Administrations"}],
    facts:[["President","Earl Warren"],["Term","20 January 1957 – 20 January 1961"],["Party","Republican"],["Vice president","Name open"],["Selection","House of Representatives after 1956 election"],["Predecessor","Thomas E. Dewey"],["Successor","John F. Kennedy"],["Defining event","German satellite shock of 1957"]]
  }),

  "kennedy-administration": administrationArticle({
    title:"Presidency of John F. Kennedy",
    portrait:{src:"assets/presidents/36-john-f-kennedy.jpg",alt:"Portrait of John F. Kennedy",caption:"John F. Kennedy, president from 1961 to 1969"},
    lead:"John F. Kennedy served as the thirty-sixth president of the United States from 20 January 1961 to 20 January 1969. His Democratic administration converted the Rocket Awakening into a national mission state, accelerated reusable aerospace and lunar programs, and established coercive associated-state intervention as the principal instrument of the American Hemisphere.",
    canon:"Kennedy's two terms, survival beyond 1963, mission politics, technical and space expansion, Hemispheric Renewal program, Honduran and Venezuelan interventions, planned Cuban operation, 1964 landslide, and 1968 transfer are established. His vice presidents, cabinet, complete domestic legislation, and later life remain open.",
    sections:[
      {id:"inauguration",title:"Inauguration and mandate",html:"<p>Kennedy won the <a href='1960-united-states-presidential-election.html'>1960 election</a> against the Republican succession and Charles Lindbergh's National Renewal challenge. His campaign treated technical lag, hemispheric penetration, and governmental hesitation as failures that constitutional activism could repair.</p>"},
      {id:"mission",title:"Mission government",html:"<p>The administration joined aerospace, nuclear power, computing, education, infrastructure, and hemispheric security as chosen public missions. Programs received explicit targets, presidential attention, procurement authority, and a language of public sacrifice without adopting one-party corporatism.</p>"},
      {id:"space",title:"Space and aerospace policy",html:"<p>Kennedy accelerated the reusable American orbital-vehicle line, heavy research, communications, and lunar planning. His challenge to the rival powers carried Warren's technical institutions into a public contest over national capacity.</p><p>The reusable Columbia architecture and later lunar program were products of this period even where flight milestones occurred under Rockefeller.</p>"},
      {id:"domestic",title:"Domestic policy",html:"<p>The <a href='hemispheric-renewal-act.html'>Hemispheric Renewal Act</a> linked technical education, industrial development, infrastructure, security institutions, and foreign economic tools. The exact cabinet and complete legislative sequence remain open.</p>"},
      {id:"honduras",title:"Honduras",html:"<p>The 1962 Honduran intervention created the first successful postwar American client administration. Advisers, security assistance, finance, and institutional reconstruction established the model later called associated-state intervention.</p>"},
      {id:"venezuela",title:"Venezuela",html:"<p>The Venezuelan concession crisis and intervention of 1963–66 were longer and bloodier. American intelligence, advisers, finance, and security forces supported a durable client regime after the <a href='maracaibo-shock.html'>Maracaibo Shock</a> exposed operational weakness.</p>"},
      {id:"second",title:"Second term",html:"<p>National Renewal tactically supported Kennedy in 1964, helping produce a landslide coalition of Democrats, Catholics, technical constituencies, and mission voters. Kennedy was not assassinated and remained responsible for the consequences of the institutions he created.</p>"},
      {id:"1968",title:"Cuba and the 1968 transition",html:"<p>Officials prepared a Cuban intervention, but the disputed 1968 election froze authorization before execution. The House selected Nelson Rockefeller after no candidate won an electoral majority.</p><p>Kennedy transferred a capable technical state together with a deeply coercive hemispheric doctrine and an unresolved legitimacy crisis.</p>"}
    ],
    related:[{href:"john-f-kennedy.html",kicker:"President",label:"John F. Kennedy"},{href:"warren-administration.html",kicker:"Predecessor government",label:"Warren Administration"},{href:"rockefeller-administration.html",kicker:"Successor government",label:"Rockefeller Administration"},{href:"hemispheric-renewal-act.html",kicker:"Principal program",label:"Hemispheric Renewal Act"},{href:"american-orbital-vehicle-program.html",kicker:"Space program",label:"American Orbital Vehicle Program"},{href:"postwar-united-states-administrations.html",kicker:"Executive sequence",label:"Postwar Administrations"}],
    facts:[["President","John F. Kennedy"],["Term","20 January 1961 – 20 January 1969"],["Party","Democratic"],["Vice president","Name open"],["Elections","1960 and 1964"],["Predecessor","Earl Warren"],["Successor","Nelson Rockefeller"],["Principal doctrine","Mission politics and associated-state intervention"]]
  }),

  "rockefeller-administration": administrationArticle({
    title:"Presidency of Nelson Rockefeller",
    portrait:{src:"assets/presidents/37-nelson-rockefeller.jpg",alt:"Portrait of Nelson Rockefeller",caption:"Nelson Rockefeller, president from 1969 to 1977"},
    lead:"Nelson Rockefeller served as the thirty-seventh president of the United States from 20 January 1969 to 20 January 1977. Chosen by the House after George Lincoln Rockwell won popular and electoral pluralities in 1968, his administration preserved the technical mission state, completed major lunar and orbital programs, and governed through the legitimacy crisis that produced the fused Democratic–Republican Party.",
    canon:"Rockefeller's House selection, two terms, Establishment Compact, Reprieve Years, technical and space continuity, 1972 fusion victory, Free Association settlement, Rockwell assassination crisis, and transfer to Buchanan are established. Both complete cabinet rosters, exact contingent ballots, and several vice-presidential details remain open.",
    sections:[
      {id:"selection",title:"House selection",html:"<p>Rockwell won the largest popular and electoral pluralities in <a href='1968-united-states-presidential-election.html'>1968</a> but no electoral majority. Democratic and Republican leaders formed the <a href='establishment-compact.html'>Establishment Compact</a>; the House selected Rockefeller and the Senate completed the vice-presidential choice.</p>"},
      {id:"mandate",title:"Mandate and administration",html:"<p>The government was constitutional but began without a popular first-place mandate. Departments inherited Kennedy's technical programs while Congress remained divided among Democrats, Republicans, and National Renewal.</p><p>Supporters described the early years as a reprieve from movement government. National Renewal called them the Stolen Mandate.</p>"},
      {id:"space",title:"Lunar and orbital programs",html:"<p>The German Moon landing of 1970 accelerated the American response. Rockefeller's administration sustained the reusable transportation sequence, the American lunar landing, permanent lunar operations, and the construction program that produced Orbital Port Columbia.</p><p>Technical achievement supplied common legitimacy but did not settle which coalition deserved political ownership of the mission state.</p>"},
      {id:"fusion",title:"Democratic–Republican fusion",html:"<p>Democrats and Republicans formalized their coalition for the <a href='1972-united-states-presidential-election.html'>1972 election</a>. Rockefeller and working running mate Henry M. Jackson defeated Rockwell approximately 51–49 while National Renewal gained Congress.</p>"},
      {id:"association",title:"Free Association settlement",html:"<p>The <a href='free-association-amendment.html'>Free Association Amendment</a> restricted federal anti-discrimination power in private institutions. Its supporters defended voluntary association; its opponents identified constitutional protection for exclusion and private dependency.</p>"},
      {id:"foreign",title:"Foreign policy",html:"<p>The administration maintained the Mid-Atlantic settlement and the American Hemisphere while avoiding a new intervention on Cuba during the legitimacy crisis. Technical competition and client politics continued below the threshold of general war.</p>"},
      {id:"assassination",title:"Rockwell assassination",html:"<p>Rockwell's murder in 1975 intensified suspicion that the constitutional establishment had denied and then removed the movement's leader. Pat Buchanan prevented retaliatory mobilization and succeeded him within National Renewal.</p>"},
      {id:"transfer",title:"Election of 1976 and legacy",html:"<p>Buchanan narrowly won the 1976 election and took office on 20 January 1977. Rockefeller's administration left intact the technical state and constitutional order, but its first selection remained the grievance around which National Renewal built a governing majority.</p>"}
    ],
    related:[{href:"nelson-rockefeller.html",kicker:"President",label:"Nelson Rockefeller"},{href:"kennedy-administration.html",kicker:"Predecessor government",label:"Kennedy Administration"},{href:"buchanan-administration.html",kicker:"Successor government",label:"Buchanan Administration"},{href:"establishment-compact.html",kicker:"Governing coalition",label:"Establishment Compact"},{href:"stolen-mandate.html",kicker:"Legitimacy crisis",label:"Stolen Mandate"},{href:"postwar-united-states-administrations.html",kicker:"Executive sequence",label:"Postwar Administrations"}],
    facts:[["President","Nelson Rockefeller"],["Term","20 January 1969 – 20 January 1977"],["Party","Republican; Democratic–Republican after 1972"],["First selection","House after 1968 election"],["Election","1972"],["Predecessor","John F. Kennedy"],["Successor","Pat Buchanan"],["Defining political issue","Stolen Mandate legitimacy crisis"]]
  }),

  "buchanan-administration": administrationArticle({
    title:"Presidency of Pat Buchanan",
    portrait:{src:"assets/presidents/38-pat-buchanan.jpg",alt:"Portrait of Pat Buchanan",caption:"Pat Buchanan, president from 1977 to 1985"},
    lead:"Pat Buchanan served as the thirty-eighth president of the United States from 20 January 1977 to 20 January 1985. His National Renewal administration governed under the formula Peace, Production, and Ascent, combining industrial modernization, technical education, personal computing, space infrastructure, family policy, and hemispheric security while rejecting proposals to replace constitutional pluralism with a formal party state.",
    canon:"Buchanan's two terms, Howard Phillips vice presidency, Shelley Buchanan's public role, productive-enterprise program, Rockwell Commission, 1980 landslide, Unity Amendment defeat, 1982 correction, commercial détente, Falklands mediation, 1984 succession, and peaceful transfer are established. The cabinet and complete statutory record remain open.",
    sections:[
      {id:"inauguration",title:"Inauguration and organization",html:"<p>Buchanan and Howard Phillips took office after a narrow <a href='1976-united-states-presidential-election.html'>1976 victory</a>. National Renewal controlled the House while Democratic–Republicans retained the Senate, requiring negotiation during the first term.</p><p>Shelley Buchanan became an active First Lady in access, presentation, and the administration's account of family life.</p>"},
      {id:"program",title:"Peace, Production, and Ascent",html:"<p>The <a href='national-mission-productive-enterprise-act.html'>National Mission and Productive Enterprise Act</a> joined Columbia, lunar construction, spaceplanes, microelectronics, machine tools, modernization finance, procurement, retraining, and National Production Institutes.</p><p>Credits remained political and sometimes protected firms lacking the technical staff or demand to use them well.</p>"},
      {id:"computing",title:"Computing and communications",html:"<p>Federal procurement, schools, semiconductor research, telecommunications, and small-business incentives helped personal computing become the program's least directed major success. Stores, clubs, spreadsheets, word processing, home programming, arcade games, and electronic publishing grew outside any single federal design.</p><p>The American Data Network later connected government, universities, banks, contractors, newspapers, and local boards.</p>"},
      {id:"commission",title:"Rockwell Commission",html:"<p>The 1978 <a href='rockwell-commission.html'>Rockwell Commission</a> concluded that the man executed for Rockwell's murder was probably wrongly convicted and that contrary evidence had been suppressed. The finding vindicated distrust of the earlier investigation without establishing the larger establishment conspiracy claimed by party militants.</p>"},
      {id:"high",title:"Second term",html:"<p>Buchanan defeated Ronald Reagan approximately 59–41 in 1980. National Renewal entered the second term with commanding congressional majorities and responsibility for the institutions it had previously criticized.</p>"},
      {id:"limits",title:"Constitutional limits",html:"<p>The 1981 <a href='national-unity-amendment.html'>National Unity and Constitutional Defense Amendment</a> proposed party registration, loyalty conditions, occupational representation, and emergency synchronization. Buchanan stopped it in committee and rejected a federal party militia, suspended opposition, and permanent emergency rule.</p>"},
      {id:"recession",title:"Productivity recession",html:"<p>The 1982 recession exposed failed automation, duplicated electronics ventures, and favored borrowers. The <a href='american-productive-commonwealth-act.html'>American Productive Commonwealth Act</a> conditioned further aid on training, audits, domestic production, technical competence, demand, and limits on executive extraction.</p>"},
      {id:"foreign",title:"Foreign and strategic policy",html:"<p>The administration maintained immigration restriction, domestic strategic production, space and defense programs, and a coercive Monroe system while permitting bounded commercial détente. In the Falklands crisis Buchanan imposed armed mediation intended to prevent either German penetration or unrestricted British escalation.</p>"},
      {id:"transfer",title:"Election of 1984 and transfer",html:"<p>Ronald Reagan defeated Phillips and Gabriel Landry in 1984. Buchanan certified the result, protected records and mission schedules, barred partisan use of security agencies, and ordered full cooperation.</p><p>The transfer on 20 January 1985 demonstrated that National Renewal could leave office lawfully and became one of Buchanan's principal constitutional legacies.</p>"}
    ],
    related:[{href:"pat-buchanan.html",kicker:"President",label:"Pat Buchanan"},{href:"rockefeller-administration.html",kicker:"Predecessor government",label:"Rockefeller Administration"},{href:"reagan-administration.html",kicker:"Successor government",label:"Reagan Administration"},{href:"national-mission-productive-enterprise-act.html",kicker:"Principal statute",label:"Mission and Productive Enterprise Act"},{href:"buchananism.html",kicker:"Governing doctrine",label:"Buchananism"},{href:"postwar-united-states-administrations.html",kicker:"Executive sequence",label:"Postwar Administrations"}],
    facts:[["President","Pat Buchanan"],["Term","20 January 1977 – 20 January 1985"],["Party","National Renewal"],["Vice president","Howard Phillips"],["Elections","1976 and 1980"],["Predecessor","Nelson Rockefeller"],["Successor","Ronald Reagan"],["Governing formula","Peace, Production, and Ascent"]]
  }),

  "reagan-administration": administrationArticle({
    title:"Presidency of Ronald Reagan",
    portrait:{src:"assets/presidents/39-ronald-reagan.jpg",alt:"Official portrait of Ronald Reagan",caption:"Ronald Reagan, president from 1985 to 1993"},
    lead:"Ronald Reagan served as the thirty-ninth president of the United States from 20 January 1985 to 20 January 1993. His Democratic–Republican administration preserved major National Renewal space and defense programs, opened trade and investment through Reciprocal Open Markets, and governed first through the World Market Boom and then through the Open Door Depression that ended the two-party order.",
    canon:"Reagan's two terms, working Jack Kemp vice presidency, Falklands rules, open-market legislation, 1986 congressional victory, Halifax Understanding, 1988 reelection, ownership investigation, Integrity Act, Great Sell-Off, depression legislation, 1990 congressional defeat, income-tax repeal, and transfer to Harwood are established. The cabinet and several statutory dates remain open.",
    sections:[
      {id:"transition",title:"Transition and divided government",html:"<p>Reagan and working vice president Jack Kemp took office through the first peaceful party transfer since National Renewal's rise. The new administration preserved defense, Columbia, Kennedy Station, Project Pilgrim, and Falklands schedules while National Renewal retained a narrow House majority.</p>"},
      {id:"falklands",title:"Falklands policy",html:"<p>The Five Falklands Rules barred conquest, German combat penetration, British mainland attack except immediate response, covert German formations, and settlement without islander consent. American surveillance tilted toward Britain after German support became clear while preserving an exit for Argentina.</p><p>Washington helped broker the Punta del Este Protocols after Stanley fell in 1986.</p>"},
      {id:"markets",title:"Reciprocal Open Markets",html:"<p>The 1985 American Open Markets and Reciprocal Investment Act began the decisive commercial opening. The 1987 Reciprocal Commerce and Enterprise Act standardized access and investor-specific caps while retaining formal restrictions on weapons, nuclear systems, launch, ports, strategic communications, and emergency capacity.</p><p>The rules did not aggregate related holdings across nominees, funds, banks, and affiliates.</p>"},
      {id:"congress",title:"Congress and reelection",html:"<p>Democratic–Republicans captured both chambers in 1986, enabling the main commercial program. Reagan, David Ashcombe, and Canada concluded the <a href='halifax-understanding.html'>Halifax Understanding</a> in 1988. Reagan defeated Bell and Kincaid approximately 58–41 later that year.</p>"},
      {id:"boom",title:"World Market Boom",html:"<p>Investment, employment, household wealth, computing, exports, commercial space, and consumer choice expanded from 1985 to 1989. Leverage, overvaluation, concealed control, and speculative dependence grew at the same time.</p><p>The boom was a period of real production and a period of accumulating ownership risk.</p>"},
      {id:"ownership",title:"Ownership investigation",html:"<p>An interagency project used the American Data Network to reconcile registries, bank custody, voting agreements, nominees, and funds. Its May 1990 report showed effective foreign control far beyond the apparent statutory limits. The report leaked in June.</p><p>The National Industrial Integrity Act ordered divestiture of prohibited and aggregated positions.</p>"},
      {id:"depression",title:"Open Door Depression",html:"<p>Forced foreign liquidation and domestic panic produced the <a href='great-sell-off.html'>Great Sell-Off</a> of September and October 1990. Equity, collateral, credit, pensions, orders, and employment collapsed together.</p><p>National Renewal won approximately 300–320 House seats and 60–64 Senate seats in November.</p>"},
      {id:"recovery",title:"Depression government",html:"<p>Reagan accepted emergency finance, bankruptcy, employment, and recovery measures while vetoing compulsory corporatist programs. Congress repealed the individual federal income tax over his veto in 1991 or early 1992.</p><p>Domestic incorporation, merger, bankruptcy, concessions, and finance were liberalized while inherited strategic ownership was closed, producing the rule called open commerce, closed control.</p>"},
      {id:"legacy",title:"Election of 1992 and legacy",html:"<p>Thomas Harwood defeated Andrew Hale in 1992 after the crash validated National Renewal's ownership warnings. Reagan transferred office on 20 January 1993.</p><p>Assessments of the administration remain divided between the prosperity and compatibility created by opening and the regulatory failure and compressed correction that produced the Second Great Depression.</p>"}
    ],
    related:[{href:"ronald-reagan.html",kicker:"President",label:"Ronald Reagan"},{href:"reagan-era.html",kicker:"Wider period",label:"Reagan Era"},{href:"buchanan-administration.html",kicker:"Predecessor government",label:"Buchanan Administration"},{href:"harwood-administration.html",kicker:"Successor government",label:"Harwood Administration"},{href:"world-market-boom.html",kicker:"First-term economy",label:"World Market Boom"},{href:"open-door-depression.html",kicker:"Second-term crisis",label:"Open Door Depression"},{href:"postwar-united-states-administrations.html",kicker:"Executive sequence",label:"Postwar Administrations"}],
    facts:[["President","Ronald Reagan"],["Term","20 January 1985 – 20 January 1993"],["Party","Democratic–Republican"],["Vice president","Jack Kemp · working canon"],["Elections","1984 and 1988"],["Predecessor","Pat Buchanan"],["Successor","Thomas Harwood"],["Defining cycle","World Market Boom and Open Door Depression"]]
  }),

  "harwood-administration": administrationArticle({
    title:"Presidency of Thomas Harwood",
    lead:"Thomas Harwood served as the fortieth president of the United States from 20 January 1993 to 20 January 1997. Elected with National Renewal congressional supermajorities after the Open Door Depression, he attempted to organize reconstruction through chartered industries and binding sector councils. His effort to discipline the party caucus produced the National Renewal schism and the mature five-party republic.",
    canon:"Harwood's term, Nathaniel Bell vice presidency, 1992 victory, Productive Commonwealth doctrine, caucus-binding and committee purge attempt, 1993 schism, Frontier National Orbital Carrier charter, elector-allocation reforms, 1996 contingent defeat, and transfer to Hale are established. His full cabinet, most later legislation, exact election coalition, and private biography remain open.",
    sections:[
      {id:"inauguration",title:"Inauguration and congressional position",html:"<p>Harwood and Nathaniel Reed Bell took office after winning approximately 51.0 percent and 286 electoral votes in <a href='1992-united-states-presidential-election.html'>1992</a>. National Renewal held roughly 300–305 House seats and 68–69 senators.</p><p>Split-ticket voting meant the congressional majority contained many constitutionalists, producer federalists, agrarians, mission technocrats, and old guards who had not endorsed Harwood's full program.</p>"},
      {id:"doctrine",title:"Productive Commonwealth program",html:"<p>Harwood proposed chartered domestic industries, sector councils, family wages, reserve capacity, closed strategic ownership, training duties, closure review, and public obligations attached to productive privilege.</p><p>The councils were intended to join firms, recognized labor, engineers, governments, banks, and federal representatives without necessarily transferring formal ownership to the state.</p>"},
      {id:"schism",title:"National Renewal schism",html:"<p>Harwood attempted to bind the congressional caucus to the program and remove dissenting committee chairs. Control of campaign funds, state officers, and ballot eligibility turned a policy dispute into an organizational survival conflict.</p><p>The 1993 schism left Harwood's National Renewal beside Constitutional Renewal, American Producers, National Vanguard, and the Democratic–Republican Party.</p>"},
      {id:"administration",title:"Administration after the schism",html:"<p>The presidency retained executive authority, but no replacement party commanded the pre-schism supermajority. Legislation depended on issue coalitions among the five organizations, state delegations, and corporate or regional interests.</p><p>The full cabinet and most later domestic enactments remain unsettled.</p>"},
      {id:"frontier",title:"Frontier national charter",html:"<p>Harwood chartered Frontier Orbital Lines as a <a href='national-orbital-carrier.html'>National Orbital Carrier</a> in 1993. Private operation received privileged access and obligations for strategic lift, public missions, emergency service, and continuity.</p><p><a href='project-switchback.html'>Project Switchback</a> began reusable vertical-rocket development without replacing Frontier's spaceplane fleet.</p>"},
      {id:"electors",title:"Electoral reform",html:"<p>Between 1993 and 1996, states increasingly assigned electors proportionally or by district. The reforms reflected the new five-party vote and made a national Electoral College majority increasingly unlikely.</p><p>The Constitution remained unchanged: the House selected among the top three whenever no electoral majority existed.</p>"},
      {id:"foreign",title:"Foreign and strategic policy",html:"<p>Harwood preserved closed strategic ownership, continental defense, existing hemisphere commitments, and major space infrastructure. The weakened party system limited any rapid replacement of Reagan's commercial relationships or withdrawal from the Armed Concert.</p>"},
      {id:"1996",title:"Election of 1996",html:"<p>No candidate secured an electoral majority in 1996. Harwood remained one of several national contenders, but the House selected Andrew Prescott Hale after multiple ballots as a bounded stability choice.</p><p>Harwood transferred office on 20 January 1997. His administration is remembered for a partly vindicated diagnosis of foreign control and an organizational remedy that destroyed the unified party expected to carry it.</p>"}
    ],
    related:[{href:"thomas-harwood.html",kicker:"President",label:"Thomas Harwood"},{href:"reagan-administration.html",kicker:"Predecessor government",label:"Reagan Administration"},{href:"hale-administration.html",kicker:"Successor government",label:"Hale Administration"},{href:"productive-commonwealth-faction.html",kicker:"Governing doctrine",label:"Productive Commonwealth"},{href:"1993-national-renewal-schism.html",kicker:"Defining crisis",label:"1993 National Renewal Schism"},{href:"national-orbital-carrier.html",kicker:"Space charter",label:"National Orbital Carrier"},{href:"postwar-united-states-administrations.html",kicker:"Executive sequence",label:"Postwar Administrations"}],
    facts:[["President","Thomas Harwood"],["Term","20 January 1993 – 20 January 1997"],["Party","National Renewal / Productive current"],["Vice president","Nathaniel Reed Bell"],["Election","1992"],["Predecessor","Ronald Reagan"],["Successor","Andrew Prescott Hale"],["Defining crisis","1993 National Renewal schism"]]
  })
});

function appendAdministrationRelated(key, item) {
  const article = window.deepArticles[key];
  if (!article) return;
  article.related = article.related || [];
  if (!article.related.some(existing => existing.href === item.href)) article.related.push(item);
}

